examples.code:
-- expand: add new column, nullable, backfill in batches
ALTER TABLE orders ADD COLUMN currency TEXT;
UPDATE orders SET currency = 'EUR' WHERE currency IS NULL;

-- contract (later release): enforce + drop old
ALTER TABLE orders ALTER COLUMN currency SET NOT NULL;

-- constraint as last line of defense
ALTER TABLE orders ADD CONSTRAINT total_nonneg CHECK (total_cents >= 0);

